using System;using System.IO;using System.Linq;using UnityEngine;using UnityEngine.UI;using TMPro;using Bokumyaku.Presentation;
public static class HudPanelHomeCheck {public static object Run(){var g=UnityEngine.Object.FindFirstObjectByType<BokumyakuGame>();if(!g.SavePath.Contains("ink-qa-"))throw new Exception("Isolated only");var snapshot=JsonUtility.ToJson(g.Run.CaptureState());g.SetPage(BokumyakuGame.GamePage.Battle);var hud=UnityEngine.Object.FindFirstObjectByType<BokumyakuBattleHud>();var buttons=hud.GetComponentsInChildren<Button>();var pause=buttons.Single(b=>b.name=="Pause");bool wasPaused=g.IsPaused;pause.onClick.Invoke();if(g.IsPaused==wasPaused)throw new Exception("Pause callback");pause.onClick.Invoke();buttons.Single(b=>b.name=="Home").onClick.Invoke();if(g.Page!=BokumyakuGame.GamePage.Home)throw new Exception("Home callback");Canvas.ForceUpdateCanvases();var menu=UnityEngine.Object.FindFirstObjectByType<BokumyakuMenuHud>();foreach(var t in menu.GetComponentsInChildren<TextMeshProUGUI>()){t.ForceMeshUpdate();if(t.isTextOverflowing)throw new Exception("Overflow "+t.name);}if(snapshot!=JsonUtility.ToJson(g.Run.CaptureState()))throw new Exception("Run changed");ScreenCapture.CaptureScreenshot(Path.GetFullPath("../docs/evidence/hud-panel-home.png"));var r=new{passed=true,width=Screen.width,height=Screen.height,snapshotUnchanged=true,pauseAndHomeCallbacks=true};File.WriteAllText(Path.GetFullPath("../docs/evidence/hud-panel-home.json"),Newtonsoft.Json.JsonConvert.SerializeObject(r));return r;}}
